#include <vector>
#include <string>
struct Ev { bool buy; long long size; };
int ofiSignal(const std::vector<Ev>& ev, int w){
    int n = ev.size();
    long long buys = 0, sells = 0;
    for (int i = std::max(0, n - w); i < n; i++){
        if (ev[i].buy) buys += ev[i].size; else sells += ev[i].size;
    }
    long long tot = buys + sells;
    if (tot == 0) return 0;
    double ofi = (double)(buys - sells) / tot;
    if (ofi > 0.3) return 1;
    if (ofi < -0.3) return -1;
    return 0;
}
